return $input.all().map((item) => {
  const j = item.json || {};
  const from = String(j.from || '');
  const raw = String(j.textPlain || j.text || j.snippet || j.mail || '');
  const headers = j.headers || {};
  const msgId = String(j.messageId || headers['message-id'] || j['Message-ID'] || ('msg-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7))).replace(/[<>]/g, '');
  const threadId = String(j.threadId || headers['x-gm-threadid'] || headers['X-GM-THRID'] || msgId).replace(/[<>]/g, '');
  const senderMatch = from.match(/<([^<>]+)>/) || from.match(/([^\s<>@]+@[^\s<>]+)/);
  return { json: {
    gmailMessageId: msgId,
    threadId: threadId,
    sender: from.slice(0, 300),
    senderEmail: (senderMatch ? senderMatch[1] : from).trim().toLowerCase(),
    subject: String(j.subject || j.Subject || '').slice(0, 500),
    bodySnippet: raw.slice(0, 500),
    bodyFull: raw.slice(0, 3000),
    receivedAt: j.date ? new Date(j.date).toISOString() : new Date().toISOString(),
    labels: ['INBOX']
  }};
});
